import fs from 'node:fs';

const read=file=>fs.readFileSync(file,'utf8');
const write=(file,text)=>fs.writeFileSync(file,text);
const must=(condition,message)=>{if(!condition)throw new Error(message);};
const replaceOnce=(text,from,to,label)=>{must(text.includes(from),`Missing patch anchor: ${label}`);return text.replace(from,to);};
const replaceFunctionBody=(text,name,body)=>{
  const marker=`function ${name}(`,start=text.indexOf(marker);must(start>=0,`Missing function ${name}`);
  const open=text.indexOf('{',start);must(open>=0,`Missing body for ${name}`);let depth=0,end=-1,inString=null,escape=false;
  for(let i=open;i<text.length;i++){
    const c=text[i];
    if(inString){if(escape){escape=false;continue;}if(c==='\\'){escape=true;continue;}if(c===inString)inString=null;continue;}
    if(c==='"'||c==="'"||c==='`'){inString=c;continue;}
    if(c==='{')depth++;else if(c==='}'&&--depth===0){end=i;break;}
  }
  must(end>open,`Could not parse function ${name}`);
  return text.slice(0,open+1)+body+text.slice(end);
};
const injectFunctionStart=(text,name,code)=>{
  const marker=`function ${name}(`,start=text.indexOf(marker);must(start>=0,`Missing function ${name}`);const open=text.indexOf('{',start);must(open>=0,`Missing body for ${name}`);return text.slice(0,open+1)+code+text.slice(open+1);
};

