function decimalCompare(a,b){const x=decimalParts(a),y=decimalParts(b);if(!x||!y)return null;const scale=Math.max(x.frac.length,y.frac.length),toBig=p=>BigInt((p.neg?'-':'')+(p.int+(p.frac+'0'.repeat(scale)).slice(0,scale)));const xb=toBig(x),yb=toBig(y);return xb===yb?0:xb<yb?-1:1;}
function numericRelation(actual,expected,op,step){const abs=step.absoluteTolerance,rel=step.relativeTolerance;if(abs!==undefined||rel!==undefined){const a=Number(actual),e=Number(expected);if(!Number.isFinite(a)||!Number.isFinite(e))return false;const tolerance=Math.max(Number(abs||0),Math.abs(e)*Number(rel||0));if(op==='EQ')return Math.abs(a-e)<=tolerance;}const exact=decimalCompare(actual,expected);if(exact!==null){if(op==='EQ')return exact===0;if(op==='GT')return exact>0;if(op==='GTE')return exact>=0;if(op==='LT')return exact<0;if(op==='LTE')return exact<=0;}const a=Number(actual),e=Number(expected);if(!Number.isFinite(a)||!Number.isFinite(e))return false;if(op==='EQ')return a===e;if(op==='GT')return a>e;if(op==='GTE')return a>=e;if(op==='LT')return a<e;return a<=e;}
function validateBindings(bindings){const issues=[];if(!bindings||typeof bindings!=='object'||Array.isArray(bindings))return {valid:false,issues:['Bindings must be an object.']};for(const [name,b] of Object.entries(bindings)){if(!/^[A-Z][A-Z0-9_]{0,63}$/.test(name))issues.push('Invalid binding '+name+'.');if(typeof b==='string')continue;if(!b||typeof b!=='object'||Array.isArray(b)){issues.push('Binding '+name+' must be an artifact ID string or closed object.');continue;}const allowed=['artifactId','source','artifactRole','filename','canonicalPath','value'];for(const k of Object.keys(b))if(!allowed.includes(k))issues.push('Binding '+name+' contains unsupported key '+k+'.');if(b.source&&!['CURRENT_PRODUCT','CURRENT_SCOPE','CANONICAL_VALUE'].includes(b.source))issues.push('Binding '+name+' has unsupported source.');if(!b.artifactId&&!b.artifactRole&&!b.filename&&!b.canonicalPath)issues.push('Binding '+name+' identifies no permitted input.');}return {valid:issues.length===0,issues};}
function validateSpec(spec,bindings={}){const issues=[];if(!spec||typeof spec!=='object'||Array.isArray(spec))issues.push('Test IR must be an object.');if(spec?.version!==SPEC_VERSION)issues.push('Unsupported Test IR version.');if(!Array.isArray(spec?.steps)||!spec.steps.length)issues.push('Test IR requires steps.');if((spec?.steps?.length||0)>LIMITS.maxSteps)issues.push('Test IR exceeds step limit.');for(const [i,step] of (spec?.steps||[]).entries()){if(!step||typeof step!=='object'||Array.isArray(step)){issues.push('Step '+i+' is not an object.');continue;}const c=CONTRACTS[step.op];if(!c){issues.push('Step '+i+' uses unsupported operation '+String(step.op)+'.');continue;}for(const key of Object.keys(step))if(!c.allowed.includes(key))issues.push('Step '+i+' contains unknown property '+key+'.');for(const key of c.required)if(!Object.prototype.hasOwnProperty.call(step,key))issues.push('Step '+i+' is missing '+key+'.');if(step.op==='SELECT_JSON_PATH'||step.op==='SELECT_XML')try{validateSelector(step.path,step.op==='SELECT_XML'?'xml':'json');}catch(e){issues.push('Step '+i+': '+e.message);}if(step.op==='REGEX'||step.op==='ASSERT_MATCH')try{safeRegex(step.pattern??step.value??'',step.flags||'');}catch(e){issues.push('Step '+i+': '+e.message);}if(step.op==='ASSERT_EQ'&&typeof step.value==='number'&&!Number.isInteger(step.value)&&step.absoluteTolerance===undefined&&step.relativeTolerance===undefined)issues.push('Step '+i+' decimal numeric equality requires explicit tolerance or an exact decimal string.');if(step.op==='PARSE_CSV'&&step.encoding!=='UTF-8')issues.push('Step '+i+' CSV encoding must be UTF-8.');}issues.push(...validateBindings(bindings).issues);return {valid:issues.length===0,issues};}
